import React, { useState } from 'react'
import Switch from './Switch'

export default {
  title: 'Components/Switch',
  component: Switch,
}

export function Small(): JSX.Element {
  const [checked, setChecked] = useState(false)

  const handleChange = (event) => {
    setChecked(event.currentTarget.checked)
  }

  return (
    <div className="flex flex-col m-6 space-y-4">
      <Switch
        color="primary"
        helperText="This is helper text"
        onChange={(event) => handleChange(event)}
        size="small"
      >
        {checked ? 'True' : 'False'}
      </Switch>

      <Switch color="secondary" helperText="This is helper text" size="small">
        Label
      </Switch>

      <Switch disabled helperText="This is helper text" size="small">
        Label
      </Switch>

      <Switch
        defaultChecked
        disabled
        helperText="This is helper text"
        size="small"
      >
        Label
      </Switch>

      <Switch
        color="secondary"
        defaultChecked
        disabled
        helperText="This is helper text"
        size="small"
      >
        Label
      </Switch>
    </div>
  )
}

export function Medium(): JSX.Element {
  const [checked, setChecked] = useState(false)

  const handleChange = (event) => {
    setChecked(event.currentTarget.checked)
  }

  return (
    <div className="flex flex-col m-6 space-y-4">
      <Switch
        color="primary"
        onChange={(event) => handleChange(event)}
        size="medium"
      >
        {checked ? 'True' : 'False'}
      </Switch>

      <Switch color="secondary" size="medium">
        Label
      </Switch>

      <Switch disabled size="medium">
        Label
      </Switch>

      <Switch defaultChecked disabled size="medium">
        Label
      </Switch>

      <Switch color="secondary" defaultChecked disabled size="medium">
        Label
      </Switch>
    </div>
  )
}
